inline const STX *GetSTX(const void *buf) {
  return ::flatbuffers::GetRoot<STX>(buf);
}

inline const STX *GetSizePrefixedSTX(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<STX>(buf);
}

inline const char *STXIdentifier() {
  return "$STX";
}

inline bool STXBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, STXIdentifier());
}

inline bool SizePrefixedSTXBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, STXIdentifier(), true);
}

template <bool B = false>
inline bool VerifySTXBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<STX>(STXIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSTXBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<STX>(STXIdentifier());
}

inline void FinishSTXBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<STX> root) {
  fbb.Finish(root, STXIdentifier());
}

inline void FinishSizePrefixedSTXBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<STX> root) {
  fbb.FinishSizePrefixed(root, STXIdentifier());
}

inline std::unique_ptr<STXT> UnPackSTX(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<STXT>(GetSTX(buf)->UnPack(res));
}

inline std::unique_ptr<STXT> UnPackSizePrefixedSTX(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<STXT>(GetSizePrefixedSTX(buf)->UnPack(res));
}

